import{_ as i,o as l,c as t,ae as o}from"./chunks/framework.RRduUuAx.js";const m=JSON.parse('{"title":"Policy Rule Model and Storage","description":"","frontmatter":{"work_package_id":"WP01","title":"Policy Rule Model and Storage","lane":"done","dependencies":[],"base_branch":"main","base_commit":"b60720e55a9bdcd25f2d7a49039abeb9ee2b33b7","created_at":"2026-03-01T13:34:08.526724+00:00","subtasks":["T001","T002","T003","T004","T005"],"phase":"Phase 1 - Policy Foundation","assignee":"","agent":"claude-haiku","shell_pid":"73312","review_status":"approved","reviewed_by":"Koosha Paridehpour","history":[{"timestamp":"2026-02-27T00:00:00Z","lane":"planned","agent":"system","shell_pid":"","action":"Prompt generated via /spec-kitty.tasks"}]},"headers":[],"relativePath":"specs/023-command-policy-engine-and-approval-workflows/tasks/WP01-policy-rule-model-and-storage.md","filePath":"specs/023-command-policy-engine-and-approval-workflows/tasks/WP01-policy-rule-model-and-storage.md"}'),a={name:"specs/023-command-policy-engine-and-approval-workflows/tasks/WP01-policy-rule-model-and-storage.md"};function s(r,e,c,n,d,u){return l(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="work-package-prompt-wp01-policy-rule-model-and-storage" tabindex="-1">Work Package Prompt: WP01 - Policy Rule Model and Storage <a class="header-anchor" href="#work-package-prompt-wp01-policy-rule-model-and-storage" aria-label="Permalink to &quot;Work Package Prompt: WP01 - Policy Rule Model and Storage&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Define the PolicyRule and PolicyRuleSet types with pattern matching, classification, and conflict resolution.</li><li>Implement rule storage with in-memory cache and file-backed persistence.</li><li>Ensure deny-by-default for all unmatched commands.</li><li>Support hot-swap rule updates within 1 second.</li></ul><p>Success criteria:</p><ul><li>PolicyRuleSet correctly classifies commands as safe, needs-approval, or blocked.</li><li>Denylist patterns override allowlist patterns in all conflict scenarios.</li><li>Unmatched commands are denied by default.</li><li>Rule updates take effect within 1 second without restart.</li><li>All classification logic is tested with edge cases.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/023-command-policy-engine-and-approval-workflows/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/023-command-policy-engine-and-approval-workflows/spec.md</code></li></ul><p>Constraints:</p><ul><li>Policy evaluation &lt; 50ms (p95) for up to 500 rules (NFR-023-001).</li><li>Deny-by-default is mandatory; no implicit allow.</li><li>Denylist always wins over allowlist.</li><li>Keep files under repository limits (target &lt;=350 lines, hard &lt;=500).</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP01</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t001-define-policyrule-type" tabindex="-1">Subtask T001 - Define PolicyRule type <a class="header-anchor" href="#subtask-t001-define-policyrule-type" aria-label="Permalink to &quot;Subtask T001 - Define PolicyRule type&quot;">​</a></h3><ul><li>Purpose: Establish the foundational data model for individual policy rules.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/policy/types.ts</code>.</li><li>Define <code>PolicyClassification</code> enum: <code>&quot;safe&quot;</code>, <code>&quot;needs-approval&quot;</code>, <code>&quot;blocked&quot;</code>.</li><li>Define <code>PolicyPatternType</code> enum: <code>&quot;glob&quot;</code>, <code>&quot;regex&quot;</code>.</li><li>Define <code>PolicyRule</code> interface: <ul><li><code>id</code>: unique string identifier</li><li><code>pattern</code>: string (glob or regex pattern to match against command text)</li><li><code>patternType</code>: PolicyPatternType</li><li><code>classification</code>: PolicyClassification</li><li><code>scope</code>: string (workspace ID this rule applies to)</li><li><code>priority</code>: number (lower = higher priority, used for ordering)</li><li><code>description</code>: string (human-readable explanation)</li><li><code>targets</code>: optional array of path patterns this rule applies to (for file-targeting commands)</li><li><code>createdAt</code>: ISO 8601 timestamp</li><li><code>updatedAt</code>: ISO 8601 timestamp</li></ul></li><li>Define <code>PolicyRuleInput</code> type for creating/updating rules (omitting computed fields).</li><li>Add JSDoc comments explaining each field&#39;s purpose and constraints.</li><li>Export all types for use by the engine and storage modules.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/policy/types.ts</code></li></ul></li><li>Acceptance: <ul><li>All types exported and documented.</li><li>Classification enum covers all three states.</li><li>Pattern type supports both glob and regex.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t002-implement-policyruleset-with-denylist-wins-conflict-resolution" tabindex="-1">Subtask T002 - Implement PolicyRuleSet with denylist-wins conflict resolution <a class="header-anchor" href="#subtask-t002-implement-policyruleset-with-denylist-wins-conflict-resolution" aria-label="Permalink to &quot;Subtask T002 - Implement PolicyRuleSet with denylist-wins conflict resolution&quot;">​</a></h3><ul><li>Purpose: Provide ordered rule evaluation with deterministic conflict resolution.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/policy/rules.ts</code>.</li><li>Implement <code>PolicyRuleSet</code> class that holds an ordered array of rules for a workspace.</li><li>Implement <code>evaluate(command: string, context: CommandContext)</code> method that: a. Iterates rules in priority order. b. Tests each rule&#39;s pattern against the command text (glob via micromatch or regex via RegExp). c. If file targets are specified, also tests against the command&#39;s affected paths. d. Collects all matching rules. e. Applies conflict resolution: if any matching rule has classification <code>&quot;blocked&quot;</code>, the result is blocked (denylist-wins). Among remaining, most restrictive wins (<code>needs-approval</code> &gt; <code>safe</code>). f. If no rules match, returns <code>&quot;blocked&quot;</code> (deny-by-default).</li><li>Return a <code>PolicyEvaluationResult</code> containing: matched rules, final classification, evaluation duration (ms), and the deny-by-default flag if triggered.</li><li>Pre-compile regex patterns on rule load for evaluation performance.</li><li>Add <code>CommandContext</code> interface: <code>workspaceId</code>, <code>agentId</code>, <code>affectedPaths</code>, <code>isDirect</code> (operator vs agent).</li><li>Implement <code>addRule</code>, <code>removeRule</code>, <code>updateRule</code> methods that maintain sorted order.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/policy/rules.ts</code></li></ul></li><li>Acceptance: <ul><li>Denylist-wins conflict resolution works correctly.</li><li>Deny-by-default for unmatched commands.</li><li>Pre-compiled patterns for performance.</li><li>Evaluation returns complete result with matched rules.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t003-implement-rule-storage-with-memory-cache-and-file-persistence" tabindex="-1">Subtask T003 - Implement rule storage with memory cache and file persistence <a class="header-anchor" href="#subtask-t003-implement-rule-storage-with-memory-cache-and-file-persistence" aria-label="Permalink to &quot;Subtask T003 - Implement rule storage with memory cache and file persistence&quot;">​</a></h3><ul><li>Purpose: Persist rules durably while maintaining fast in-memory evaluation.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/policy/storage.ts</code>.</li><li>Implement <code>PolicyStorage</code> class with: <ul><li>In-memory cache of <code>PolicyRuleSet</code> per workspace.</li><li>File-backed persistence: rules stored as JSON in a configurable location (e.g., <code>~/.helios/policies/&lt;workspaceId&gt;.json</code>).</li><li><code>loadRules(workspaceId)</code>: read from file, populate cache.</li><li><code>saveRules(workspaceId, rules)</code>: write to file atomically (temp + rename), update cache.</li><li><code>getRuleSet(workspaceId)</code>: return cached rule set, loading from file if not cached.</li></ul></li><li>Ensure file writes are atomic: write to temp file, then rename.</li><li>Handle missing policy files: return empty rule set (which means deny-by-default for all commands).</li><li>Add file watching for external policy edits.</li><li>Validate rules on load: reject malformed entries with clear error messages.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/policy/storage.ts</code></li></ul></li><li>Acceptance: <ul><li>Rules persist across process restarts.</li><li>In-memory cache is kept in sync with file.</li><li>Atomic writes prevent corruption.</li><li>Missing files handled gracefully (deny-by-default).</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t004-implement-hot-swap-rule-updates" tabindex="-1">Subtask T004 - Implement hot-swap rule updates <a class="header-anchor" href="#subtask-t004-implement-hot-swap-rule-updates" aria-label="Permalink to &quot;Subtask T004 - Implement hot-swap rule updates&quot;">​</a></h3><ul><li>Purpose: Allow policy changes to take effect immediately without process restart.</li><li>Steps: <ol><li>Implement a file watcher in <code>PolicyStorage</code> that monitors policy files for changes.</li><li>On detected change, reload rules from file and update the in-memory cache.</li><li>Ensure the update is atomic: the old rule set is used for evaluations in progress; the new rule set takes effect for the next evaluation.</li><li>Add a <code>PolicyStorage.onRulesChanged(callback)</code> event for notifying dependent components.</li><li>Publish a <code>policy.rules.updated</code> event on the local bus when rules change.</li><li>Verify the update propagation time is &lt; 1 second from file change to evaluation using new rules.</li><li>Handle edge cases: malformed policy file update (reject and keep previous rules), concurrent file modifications.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/policy/storage.ts</code> (update)</li></ul></li><li>Acceptance: <ul><li>Rule updates take effect within 1 second.</li><li>Malformed updates rejected; previous rules preserved.</li><li>Bus event published on rule change.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t005-add-unit-tests-for-rule-model-and-storage" tabindex="-1">Subtask T005 - Add unit tests for rule model and storage <a class="header-anchor" href="#subtask-t005-add-unit-tests-for-rule-model-and-storage" aria-label="Permalink to &quot;Subtask T005 - Add unit tests for rule model and storage&quot;">​</a></h3><ul><li>Purpose: Lock the policy rule model behavior with comprehensive tests.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/policy/rules.test.ts</code>.</li><li>Test: glob pattern <code>git *</code> matches <code>git status</code> and <code>git push</code> but not <code>grep git</code>.</li><li>Test: regex pattern <code>^rm\\s+-rf</code> matches <code>rm -rf /tmp</code> but not <code>echo rm -rf</code>.</li><li>Test: denylist-wins: <code>*.env</code> blocked + <code>cat *.env</code> safe -&gt; result is blocked.</li><li>Test: deny-by-default: command matching no rules returns <code>blocked</code>.</li><li>Test: priority ordering: higher-priority (lower number) rules evaluated first.</li><li>Test: file target matching: rule targeting <code>*.env</code> matches command affecting <code>.env</code> files.</li><li>Test: evaluation duration &lt; 50ms for 500 rules (performance benchmark).</li><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/policy/storage.test.ts</code>.</li><li>Test: rules persist to file and reload correctly.</li><li>Test: atomic write survives simulated crash (check temp file cleanup).</li><li>Test: hot-swap: update file, verify new rules used within 1 second.</li><li>Test: malformed file rejected; previous rules preserved.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/policy/rules.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/policy/storage.test.ts</code></li></ul></li><li>Acceptance: <ul><li>All rule matching, conflict resolution, and storage scenarios tested.</li><li>Performance benchmark passes.</li><li>Tests are deterministic.</li></ul></li><li>Parallel: Yes (after T001-T004 interfaces are defined).</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Vitest unit tests for rule matching, conflict resolution, and storage.</li><li>Performance benchmarks for evaluation latency.</li><li>Deterministic tests with no flakiness.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: Complex regex patterns slow evaluation.</li><li>Mitigation: Pre-compile; benchmark; limit pattern complexity.</li><li>Risk: File watcher misses rapid sequential updates.</li><li>Mitigation: Debounce file watch events; test with rapid updates.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm deny-by-default is enforced for unmatched commands.</li><li>Confirm denylist-wins in all conflict scenarios.</li><li>Confirm hot-swap &lt; 1 second.</li><li>Confirm no suppression directives.</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27T00:00:00Z – system – lane=planned – Prompt created.</li><li>2026-03-01T13:34:08Z – claude-haiku – shell_pid=73312 – lane=doing – Assigned agent via workflow command</li><li>2026-03-01T13:35:22Z – claude-haiku – shell_pid=73312 – lane=done – Implemented</li></ul>',30)])])}const h=i(a,[["render",s]]);export{m as __pageData,h as default};
